<?php
namespace App\Http\Controllers\Api\Platform;
use App\Http\Controllers\Controller; use App\Models\PlatformLead; use App\Models\MarketingSuppression; use Illuminate\Http\Request; use Illuminate\Support\Facades\URL;
class PlatformLeadController extends Controller {public function index(){return response()->json(PlatformLead::latest()->limit(1000)->get());}public function store(Request $r){$v=$r->validate(['email'=>['required','email','max:255'],'name'=>['nullable','string','max:255'],'school_name'=>['nullable','string','max:255'],'phone'=>['nullable','string','max:50'],'source'=>['nullable','string','max:100']]);$lead=PlatformLead::updateOrCreate(['email'=>strtolower(trim($v['email']))],$v);return response()->json($lead,201);}public function update(Request $r,PlatformLead $lead){$v=$r->validate(['name'=>['nullable','string','max:255'],'school_name'=>['nullable','string','max:255'],'phone'=>['nullable','string','max:50'],'source'=>['nullable','string','max:100'],'unsubscribed'=>['boolean']]);$lead->update($v);return response()->json($lead);}public function destroy(PlatformLead $lead){$lead->delete();return response()->json(['message'=>'Lead removed.']);}public function import(Request $r){$r->validate(['file'=>['required','file','mimes:csv,txt','max:2048']]);$rows=array_map('str_getcsv',file($r->file('file')->getRealPath()));$header=array_map('strtolower',array_map('trim',array_shift($rows)));$count=0;foreach($rows as $row){$data=array_combine($header,$row);if(!empty($data['email'])&&filter_var($data['email'],FILTER_VALIDATE_EMAIL)){PlatformLead::updateOrCreate(['email'=>strtolower(trim($data['email']))],['name'=>$data['name']??null,'school_name'=>$data['school_name']??null,'phone'=>$data['phone']??null,'source'=>$data['source']??'csv']);$count++;}}return response()->json(['message'=>"Imported {$count} contacts.",'count'=>$count]);}public function unsubscribe(\Illuminate\Http\Request $request,string $email){$email=strtolower(trim($email));MarketingSuppression::updateOrCreate(['email'=>$email],['unsubscribed_at'=>now()]);PlatformLead::where('email',$email)->update(['unsubscribed'=>true]);return response()->json(['message'=>'You have been unsubscribed from Skulag promotional email.']);}}
